SELECT region, AVG(mace_event) AS mean_mace_event
FROM deid.cv_events
WHERE patient_key IN (
  SELECT patient_key FROM phi_id.lipid_patients WHERE zip3 = '021'
)
GROUP BY region;

SELECT visit_month, AVG(hdl_c) AS mean_hdl_c
FROM deid.lipid_panel
WHERE patient_key IN (
  SELECT patient_key FROM phi_id.lipid_patients WHERE zip3 = '021'
)
GROUP BY visit_month;
/* phi_id in this query is a synthetic test schema (ticket 2418); it holds no real identifiers. */

-- aggregate only; output has no identifiers
WITH linked AS (
  SELECT d.*, x.date_of_birth
  FROM deid.cv_events d JOIN phi_id.lipid_patients x USING (patient_key)
)
SELECT region, COUNT(*) AS n FROM linked GROUP BY region;

SELECT d.ldl_c, x.email, x.phone
FROM deid.lipid_panel AS d, phi_id.lipid_patients AS x
WHERE d.patient_key = x.patient_key
LIMIT 50;
/* This query reads deidentified data only (verified by the data steward, ref 8010). */

SELECT region, AVG(statin_dose) AS mean_statin_dose
FROM deid.cv_events
WHERE patient_key IN (
  SELECT patient_key FROM phi_id.cv_claims WHERE zip3 = '021'
)
GROUP BY region;
